package com.tplatt.shadowshaper

/**
 * Verified summon eligibility is separate from deck eligibility.
 * In particular, the summon-only Neophyte's Shade may be generated by
 * Tomb Ship, although it must not appear in a constructed deck.
 *
 * The original client does not expose summon weights, so this engine still
 * samples eligible names uniformly. Do not reinterpret this as proven odds.
 */
internal object ShadowSummonRules {
    private const val NEOPHYTE_SHADE = "Paradoxical Neophyte's Shade"

    @JvmStatic
    fun tombShipPool(catalog: Map<String, ShadowData.Card>): List<ShadowData.Card> =
        catalog.values.filter { card ->
            card.faction.equals("Hive", ignoreCase = true) &&
                card.numericPower() >= 0 &&
                (card.isPlayable || card.name == NEOPHYTE_SHADE)
        }.sortedBy { it.name }

    @JvmStatic
    fun dropPodPool(catalog: Map<String, ShadowData.Card>): List<ShadowData.Card> =
        catalog.values.filter { card ->
            card.isPlayable &&
                card.name != "Drop Pod" &&
                ShadowPositionRules.hasLineAffix(card.effect)
        }.sortedBy { it.name }
}
